declare module "date-fns" {
  interface FormatOptions {
    locale?: any;
  }
  interface WeekOptions {
    weekStartsOn?: 0 | 1 | 2 | 3 | 4 | 5 | 6;
  }
  interface EachDayOfIntervalOptions extends WeekOptions {}
  export function format(date: Date | string, format: string, options?: FormatOptions): string;
  export function differenceInDays(a: Date | string, b: Date | string): number;
  export function differenceInCalendarDays(a: Date | string, b: Date | string): number;
  export function isPast(date: Date | string): boolean;
  export function isFuture(date: Date | string): boolean;
  export function isToday(date: Date | string): boolean;
  export function parseISO(dateString: string): Date;
  export function addDays(date: Date | string, days: number): Date;
  export function subDays(date: Date | string, days: number): Date;
  export function formatDistanceToNow(date: Date | string, options?: { addSuffix?: boolean }): string;
  export function formatDistanceToNowStrict(date: Date | string, options?: { addSuffix?: boolean }): string;
  export function startOfMonth(date: Date | string): Date;
  export function endOfMonth(date: Date | string): Date;
  export function startOfWeek(date: Date | string, options?: WeekOptions): Date;
  export function endOfWeek(date: Date | string, options?: WeekOptions): Date;
  export function eachDayOfInterval(
    interval: { start: Date | string; end: Date | string },
    options?: EachDayOfIntervalOptions,
  ): Date[];
  export function isSameMonth(dateLeft: Date | string, dateRight: Date | string): boolean;
  export function isSameDay(dateLeft: Date | string, dateRight: Date | string): boolean;
}

